import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const CarDetails = () => {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [car, setCar] = useState(null);
  const [loading, setLoading] = useState(true);
  const [bookingData, setBookingData] = useState({
    startDate: '',
    endDate: '',
    notes: ''
  });
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchCar();
  }, [id]);

  const fetchCar = async () => {
    try {
      const response = await axios.get(`http://localhost:8081/api/cars/public/${id}`);
      setCar(response.data);
    } catch (error) {
      console.error('Error fetching car:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleBookingChange = (e) => {
    setBookingData({
      ...bookingData,
      [e.target.name]: e.target.value
    });
  };

  const calculateTotal = () => {
    if (bookingData.startDate && bookingData.endDate) {
      const start = new Date(bookingData.startDate);
      const end = new Date(bookingData.endDate);
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
      return days * car.rentPrice;
    }
    return 0;
  };

  const handleBooking = async (e) => {
    e.preventDefault();
    
    if (!user) {
      setMessage('Please login to book a car');
      return;
    }

    if (user.role !== 'USER') {
      setMessage('Only users can book cars');
      return;
    }

    try {
      const totalAmount = calculateTotal();
      const response = await axios.post('http://localhost:8082/api/bookings/user/create', {
        carId: car.id,
        startDate: bookingData.startDate,
        endDate: bookingData.endDate,
        totalAmount: totalAmount,
        notes: bookingData.notes
      });

      setMessage('Booking created successfully!');
      setTimeout(() => {
        navigate('/my-bookings');
      }, 2000);
    } catch (error) {
      setMessage(error.response?.data?.message || 'Booking failed');
    }
  };

  if (loading) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '2rem' }}>
          <h2>Loading car details...</h2>
        </div>
      </div>
    );
  }

  if (!car) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '2rem' }}>
          <h2>Car not found</h2>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem', marginTop: '2rem' }}>
        <div>
          {car.imageUrl && (
            <img src={car.imageUrl} alt={car.name} style={{ width: '100%', borderRadius: '8px' }} />
          )}
        </div>
        
        <div>
          <h1>{car.name}</h1>
          <h2>{car.brand} {car.model} ({car.year})</h2>
          <p><strong>Price:</strong> ${car.rentPrice}/day</p>
          <p><strong>Fuel Type:</strong> {car.fuelType}</p>
          <p><strong>Transmission:</strong> {car.transmission}</p>
          <p><strong>Mileage:</strong> {car.mileage} km</p>
          <p><strong>Color:</strong> {car.color}</p>
          <p><strong>Status:</strong> {car.status}</p>
          <p><strong>Description:</strong> {car.description}</p>
          
          {user && user.role === 'USER' && (
            <div style={{ marginTop: '2rem' }}>
              <h3>Book This Car</h3>
              <form onSubmit={handleBooking}>
                <div className="form-group">
                  <label htmlFor="startDate">Start Date</label>
                  <input
                    type="date"
                    id="startDate"
                    name="startDate"
                    value={bookingData.startDate}
                    onChange={handleBookingChange}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label htmlFor="endDate">End Date</label>
                  <input
                    type="date"
                    id="endDate"
                    name="endDate"
                    value={bookingData.endDate}
                    onChange={handleBookingChange}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label htmlFor="notes">Notes (Optional)</label>
                  <textarea
                    id="notes"
                    name="notes"
                    value={bookingData.notes}
                    onChange={handleBookingChange}
                    rows="3"
                  />
                </div>
                
                {calculateTotal() > 0 && (
                  <div style={{ marginBottom: '1rem' }}>
                    <strong>Total Amount: ${calculateTotal()}</strong>
                  </div>
                )}
                
                <button type="submit" className="btn btn-success">
                  Book Now
                </button>
              </form>
            </div>
          )}
          
          {message && (
            <div className={`alert ${message.includes('successfully') ? 'alert-success' : 'alert-danger'}`}>
              {message}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CarDetails;
